import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { login, register } from '../services/auth';

export default function AuthPage() {
  const [mode, setMode] = useState('login');
  const [role, setRole] = useState('étudiant');
  const [form, setForm] = useState({ nom: '', prenom: '', email: '', password: '', date_naissance: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login: setUser } = useAuth();
  const navigate = useNavigate();

  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  async function handleSubmit(e) {
    e.preventDefault();
    setLoading(true); setError('');
    try {
      let user;
      if (mode === 'login') {
        user = await login(form.email, form.password);
      } else {
        // Envoi du formulaire simplifié
        user = await register({ ...form, role });
      }
      setUser(user);
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.detail || 'Une erreur est survenue');
    } finally {
      setLoading(false);
    }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '11px 14px', fontSize: '.9rem', width: '100%', outline: 'none' };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', background: 'var(--bg)' }}>
      {/* CÔTÉ GAUCHE (Design) */}
      <div style={{ flex: 1, background: 'linear-gradient(135deg,#1a1a2e,#16213e,#0f3460)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 24, padding: 60 }}>
        <div style={{ textAlign: 'center', marginBottom: 20 }}>
          <div style={{ fontSize: '3rem', marginBottom: 12 }}>🎓</div>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '2rem', color: '#fff' }}>EduMatch</div>
        </div>
        <div style={{ color: 'rgba(255,255,255,.8)', textAlign: 'center', maxWidth: 350 }}>Connectez-vous pour accéder à votre espace de matching intelligent.</div>
      </div>

      {/* CÔTÉ DROIT (Formulaire) */}
      <div style={{ width: 480, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 60, background: 'var(--surface)' }}>
        <form onSubmit={handleSubmit} style={{ width: '100%', maxWidth: 360 }}>
          <h2 style={{ fontFamily: 'Syne', marginBottom: 24 }}>{mode === 'login' ? '🚀 Connexion' : '📝 Inscription'}</h2>

          {/* Onglets Login / Register */}
          <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 20 }}>
            {['login', 'register'].map(m => (
              <div key={m} onClick={() => setMode(m)} style={{ flex: 1, padding: 8, textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, background: mode === m ? '#6c63ff' : 'transparent', color: mode === m ? '#fff' : 'var(--text2)' }}>
                {m === 'login' ? 'Connexion' : 'Inscription'}
              </div>
            ))}
          </div>

          {mode === 'register' && (
            <>
              {/* Choix Rôle */}
              <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 16 }}>
                {['étudiant', 'professeur'].map(r => (
                  <div key={r} onClick={() => setRole(r)} style={{ flex: 1, padding: 8, textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, background: role === r ? '#6c63ff' : 'transparent', color: role === r ? '#fff' : 'var(--text2)' }}>
                    {r === 'étudiant' ? '👨‍🎓 Étudiant' : '👨‍🏫 Professeur'}
                  </div>
                ))}
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 16 }}>
                <input style={inp} placeholder="Prénom" value={form.prenom} onChange={set('prenom')} required />
                <input style={inp} placeholder="Nom" value={form.nom} onChange={set('nom')} required />
              </div>
              <div style={{ marginBottom: 16 }}>
                <label style={{ fontSize: '.75rem', color: 'var(--text2)', display: 'block', marginBottom: 5 }}>Date de naissance</label>
                <input type="date" style={inp} value={form.date_naissance} onChange={set('date_naissance')} required />
              </div>
            </>
          )}

          <input style={{ ...inp, marginBottom: 16 }} type="email" placeholder="Email" value={form.email} onChange={set('email')} required />
          <input style={{ ...inp, marginBottom: 16 }} type="password" placeholder="Mot de passe" value={form.password} onChange={set('password')} required />

          {error && <div style={{ color: '#ff6584', fontSize: '.8rem', marginBottom: 16 }}>⚠️ {error}</div>}

          <button type="submit" disabled={loading} style={{ width: '100%', padding: 14, background: '#6c63ff', color: '#fff', border: 'none', borderRadius: 12, fontWeight: 600, cursor: 'pointer' }}>
            {loading ? 'Chargement...' : mode === 'login' ? 'Se connecter' : "S'inscrire"}
          </button>
        </form>
      </div>
    </div>
  );
}
